<?php
/**
 * Secure Credential Portal — Configuration
 *
 * SETUP STEPS:
 *  1. Run `node keygen.js` in your terminal to generate a keypair.
 *  2. Paste the public key (base64) into RSD_PUBLIC_KEY_B64 below.
 *  3. Store the private key somewhere safe and offline — never upload it.
 *  4. (Optional) Move RSD_DATA_FILE path above your public_html root in cPanel
 *     e.g. '/home/YOUR_CPANEL_USER/secure_data/submissions.json'
 */

// Your RSA-OAEP public key (SPKI, base64). Generated by keygen.js. Safe to embed here.
// Note: this will be a long string (~800 chars) — that's normal for a 4096-bit RSA key.
define('RSD_PUBLIC_KEY_B64', '');

// Path to the submissions data file.
// Default: portal/data/submissions.json — protected by .htaccess.
// Recommended: move above public_html in cPanel for better isolation,
// e.g. '/home/YOUR_CPANEL_USER/secure_data/submissions.json'
define('RSD_DATA_FILE', __DIR__ . '/data/submissions.json');
